import 'dart:convert';

import 'package:cloud_firestore/cloud_firestore.dart';

/// One test persona from `assets/seed/personas.json` (generated by
/// `tooling/persona_seed/main.dart`). Holds derived attributes only.
class DemoPersona {
  DemoPersona({
    required this.id,
    required this.displayName,
    required this.gender,
    required this.stylePreferences,
    required this.items,
    required this.outfits,
    required this.events,
  });

  final String id;
  final String displayName;
  final String gender;
  final List<String> stylePreferences;
  final List<Map<String, dynamic>> items;
  final List<Map<String, dynamic>> outfits;
  final List<Map<String, dynamic>> events;

  factory DemoPersona.fromJson(Map<String, dynamic> json) {
    return DemoPersona(
      id: json['id'] as String,
      displayName: json['displayName'] as String,
      gender: json['gender'] as String,
      stylePreferences: List<String>.from(json['stylePreferences'] as List),
      items: _asMaps(json['items']),
      outfits: _asMaps(json['outfits']),
      events: _asMaps(json['events']),
    );
  }
}

List<Map<String, dynamic>> _asMaps(Object? value) {
  return (value as List? ?? const <Object>[]).cast<Map<String, dynamic>>();
}

/// Parses the full `personas.json` document.
List<DemoPersona> parsePersonas(String rawJson) {
  final doc = jsonDecode(rawJson) as Map<String, dynamic>;
  return _asMaps(doc['personas'])
      .map(DemoPersona.fromJson)
      .toList(growable: false);
}

/// A single Firestore write, expressed without any Firestore I/O so the
/// plan can be unit tested.
class PlannedWrite {
  const PlannedWrite({
    required this.collection,
    required this.id,
    required this.data,
    this.merge = false,
  });

  final String collection;
  final String id;
  final Map<String, dynamic> data;
  final bool merge;
}

class PersonaWritePlan {
  const PersonaWritePlan({
    required this.writes,
    required this.itemCount,
    required this.outfitCount,
    required this.eventCount,
  });

  final List<PlannedWrite> writes;
  final int itemCount;
  final int outfitCount;
  final int eventCount;
}

/// Builds every Firestore write needed to give one account a persona wardrobe.
///
/// [newId] supplies document ids (Firestore auto-ids in production, fixed ids
/// in tests). Each item `localId` is mapped to a real id so outfits reference
/// stored items. Throws [StateError] if the persona data is inconsistent.
PersonaWritePlan buildPersonaWrites({
  required DemoPersona persona,
  required String userId,
  required DateTime now,
  required String Function() newId,
}) {
  final idByLocal = <String, String>{};
  for (final item in persona.items) {
    final localId = item['localId'] as String;
    if (idByLocal.containsKey(localId)) {
      throw StateError('Duplicate localId $localId in ${persona.id}.');
    }
    idByLocal[localId] = newId();
  }

  String? resolve(String? localId) {
    if (localId == null) return null;
    final id = idByLocal[localId];
    if (id == null) {
      throw StateError('Unknown item $localId referenced in ${persona.id}.');
    }
    return id;
  }

  // Marks every seeded document so the "Clear My Test Data" path can find it.
  final demoTag = <String, dynamic>{
    'is_demo': true,
    'demo_persona': persona.id,
  };

  final writes = <PlannedWrite>[];

  for (var i = 0; i < persona.items.length; i++) {
    final item = persona.items[i];
    final id = idByLocal[item['localId'] as String]!;
    final createdAt = Timestamp.fromDate(now.subtract(Duration(days: i + 1)));
    final imageUrl = item['imageUrl'] as String;
    final subcategory = item['subcategory'] as String;
    final styleTags = List<String>.from(item['styleTags'] as List);

    writes.add(PlannedWrite(
      collection: 'clothing_items',
      id: id,
      data: {
        'id': id,
        'parentCategory': item['parentCategory'],
        'subcategory': subcategory,
        'categoryType': item['categoryType'],
        if (item['fit'] != null) 'fit': item['fit'],
        'color': item['color'],
        'colorGroup': item['colorGroup'],
        'styleTags': styleTags,
        'season': item['season'],
        'status': item['status'],
        'gender': item['gender'],
        'imageUrl': imageUrl,
        'localImagePath': item['localImagePath'],
        'userId': userId,
        'user_id': userId,
        'createdAt': createdAt,
        'created_at': createdAt,
        'updatedAt': createdAt,
        'updated_at': createdAt,
        // Legacy fields read by older builds.
        'image_url': imageUrl,
        'category': subcategory,
        'style_tags': styleTags,
        ...demoTag,
      },
    ));
  }

  for (var i = 0; i < persona.outfits.length; i++) {
    final outfit = persona.outfits[i];
    final top = resolve(outfit['topLocalId'] as String?);
    final bottom = resolve(outfit['bottomLocalId'] as String?);
    final shoes = resolve(outfit['shoesLocalId'] as String?);
    final accessory = resolve(outfit['accessoryLocalId'] as String?);
    if (top == null || bottom == null || shoes == null) {
      throw StateError(
        'Outfit ${outfit['localId']} in ${persona.id} is missing a top, bottom or shoes.',
      );
    }

    final id = newId();
    final score = outfit['score'] as int;
    final summary = outfit['summary'] as String;
    final generatedAt = Timestamp.fromDate(now.subtract(Duration(days: i + 1)));

    writes.add(PlannedWrite(
      collection: 'outfit_history',
      id: id,
      data: {
        'id': id,
        'occasion': outfit['occasion'],
        'score': score,
        'caption': summary,
        'userId': userId,
        'user_id': userId,
        'generatedAt': generatedAt,
        'generated_at': generatedAt,
        'outfit': {
          'top_id': top,
          'bottom_id': bottom,
          'shoes_id': shoes,
          'accessory_id': accessory,
          'accessory_ids': [if (accessory != null) accessory],
          'score': score,
          'reasoning': [summary],
        },
        ...demoTag,
      },
    ));
  }

  for (final event in persona.events) {
    final id = newId();
    final daysFromNow = event['daysFromNow'] as int;

    writes.add(PlannedWrite(
      collection: 'events',
      id: id,
      data: {
        'id': id,
        'userId': userId,
        'user_id': userId,
        'name': event['name'],
        'occasion': event['occasion'],
        'recommended_outfits': List<String>.from(
          event['recommendedOutfits'] as List,
        ),
        'date': Timestamp.fromDate(now.add(Duration(days: daysFromNow))),
        ...demoTag,
      },
    ));
  }

  writes.add(PlannedWrite(
    collection: 'users',
    id: userId,
    merge: true,
    data: {
      'gender': persona.gender,
      'genderFilterEnabled': true,
      'stylePreferences': persona.stylePreferences,
      'style_dna': persona.stylePreferences.first,
      'demo_persona': persona.id,
      'last_seeded_at': Timestamp.fromDate(now),
      'updated_at': Timestamp.fromDate(now),
    },
  ));

  writes.add(PlannedWrite(
    collection: 'audit_events',
    id: newId(),
    data: {
      'userId': userId,
      'user_id': userId,
      'type': 'persona_seed',
      'message': 'Test persona ${persona.id} seeded.',
      'created_at': Timestamp.fromDate(now),
      ...demoTag,
    },
  ));

  return PersonaWritePlan(
    writes: writes,
    itemCount: persona.items.length,
    outfitCount: persona.outfits.length,
    eventCount: persona.events.length,
  );
}
